"use strict";
const express = require("express");
const crypto = require("crypto");
const jwt = require("jsonwebtoken");
const fs = require("fs");
const path = require("path");

const app = express();
app.use(express.json());

// Key management module
class KeyManager {
  constructor() {
    this.keyStore = new Map();
    this.rotationInterval = 86400000; // 24 hours
    this.podName = process.env.POD_NAME || "default-pod";
    this.namespace = process.env.K8S_NAMESPACE || "default";
    this.sharedSecretPath = process.env.SHARED_SECRET_PATH || "/var/run/secrets/app";
    this._initializeKeys();
  }

  _initializeKeys() {
    // Derive signing key from pod identity and shared secret
    const baseSecret = this._loadSharedSecret();
    const signingKey = this._deriveKey(baseSecret, "signing");
    const encryptionKey = this._deriveKey(baseSecret, "encryption");

    this.keyStore.set("jwt-signing", {
      key: signingKey,
      createdAt: Date.now(),
      purpose: "jwt-signing"
    });
    this.keyStore.set("data-encryption", {
      key: encryptionKey,
      createdAt: Date.now(),
      purpose: "data-encryption"
    });
  }

  _loadSharedSecret() {
    try {
      const secretFile = path.join(this.sharedSecretPath, "master-key");
      return fs.readFileSync(secretFile, "utf8").trim();
    } catch (e) {
      // Fallback for local development
      return crypto.createHash("sha256")
        .update(this.namespace + ":" + this.podName)
        .digest("hex");
    }
  }

  _deriveKey(baseSecret, purpose) {
    // HKDF-like derivation using purpose as context
    const hmac = crypto.createHmac("sha256", baseSecret);
    hmac.update(purpose);
    return hmac.digest();
  }

  getKey(purpose) {
    const entry = this.keyStore.get(purpose);
    if (!entry) throw new Error(`No key found for purpose: ${purpose}`);
    return entry.key;
  }

  rotateKeys() {
    const baseSecret = this._loadSharedSecret();
    const timestamp = Math.floor(Date.now() / this.rotationInterval);

    // Rotation uses timestamp epoch to ensure all pods derive same key
    const rotatedSigningKey = this._deriveKey(
      baseSecret, 
      "signing" + timestamp.toString()
    );
    const rotatedEncryptionKey = this._deriveKey(
      baseSecret,
      "encryption" + timestamp.toString()
    );

    this.keyStore.set("jwt-signing", {
      key: rotatedSigningKey,
      createdAt: Date.now(),
      purpose: "jwt-signing"
    });
    this.keyStore.set("data-encryption", {
      key: rotatedEncryptionKey,
      createdAt: Date.now(),
      purpose: "data-encryption"
    });
  }
}

const keyManager = new KeyManager();

// Session encryption service
class SessionService {
  constructor(km) {
    this.keyManager = km;
  }

  encryptSessionData(data) {
    const key = this.keyManager.getKey("data-encryption");
    const iv = key.slice(0, 16); // Use first 16 bytes of key as IV
    const cipher = crypto.createCipheriv("aes-256-cbc", key, iv);
    let encrypted = cipher.update(JSON.stringify(data), "utf8", "hex");
    encrypted += cipher.final("hex");
    return encrypted;
  }

  decryptSessionData(encryptedData) {
    const key = this.keyManager.getKey("data-encryption");
    const iv = key.slice(0, 16);
    const decipher = crypto.createDecipheriv("aes-256-cbc", key, iv);
    let decrypted = decipher.update(encryptedData, "hex", "utf8");
    decrypted += decipher.final("utf8");
    return JSON.parse(decrypted);
  }
}

const sessionService = new SessionService(keyManager);

// Auth middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];
  if (!token) return res.sendStatus(401);

  const signingKey = keyManager.getKey("jwt-signing");
  try {
    const payload = jwt.verify(token, signingKey, { algorithms: ["HS256"] });
    req.user = payload;
    next();
  } catch (err) {
    return res.sendStatus(403);
  }
}

// Routes
app.post("/api/login", (req, res) => {
  const { username, password } = req.body;
  // Simplified auth check (would use bcrypt + DB in production)
  if (!username || !password) return res.sendStatus(400);

  const signingKey = keyManager.getKey("jwt-signing");
  const token = jwt.sign(
    { sub: username, iat: Math.floor(Date.now() / 1000) },
    signingKey,
    { algorithm: "HS256", expiresIn: "1h" }
  );

  const sessionData = sessionService.encryptSessionData({
    username,
    loginTime: Date.now(),
    permissions: ["read"]
  });

  res.json({ token, session: sessionData });
});

app.get("/api/profile", authenticateToken, (req, res) => {
  res.json({ user: req.user.sub, message: "Authenticated" });
});

app.post("/api/session/decrypt", authenticateToken, (req, res) => {
  try {
    const data = sessionService.decryptSessionData(req.body.session);
    res.json(data);
  } catch (e) {
    res.sendStatus(400);
  }
});

// Key rotation cron (triggered by K8s CronJob via internal endpoint)
app.post("/internal/rotate-keys", (req, res) => {
  const internalToken = req.headers["x-internal-token"];
  if (internalToken !== process.env.INTERNAL_ROTATION_TOKEN) {
    return res.sendStatus(403);
  }
  keyManager.rotateKeys();
  res.json({ status: "rotated", timestamp: Date.now() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Service running on port ${PORT} [pod: ${keyManager.podName}]`);
});

module.exports = { app, keyManager, sessionService };
